import signal
import sys
import json
import hashlib
from flask import Flask, request, jsonify
from pymongo import MongoClient
from PIL import Image
import io
import base64
import re

app = Flask(__name__)
client = MongoClient('mongodb://localhost:27017/')
db = client['image_pipeline']
collection = db['processed_images']

shutdown_requested = False
pending_operations = []

def graceful_shutdown(signum, frame):
    global shutdown_requested
    shutdown_requested = True
    flush_pending_operations()
    client.close()
    sys.exit(0)

signal.signal(signal.SIGTERM, graceful_shutdown)
signal.signal(signal.SIGINT, graceful_shutdown)

def compute_image_hash(image_data):
    return hashlib.sha256(image_data).hexdigest()

def validate_filter_name(filter_name):
    """Validate filter name against allowed characters"""
    allowed_pattern = re.compile(r'^[a-zA-Z0-9_\-\.]+$')
    if allowed_pattern.match(filter_name):
        return True
    return False

def _is_scalar(value):
    """Only allow scalar values to prevent MongoDB operator injection."""
    return isinstance(value, (str, int, float, bool))

def build_query_from_metadata(metadata):
    """Build a MongoDB query from image metadata for deduplication.
    Uses a pipeline approach to construct the query safely."""
    query = {}

    if 'image_hash' in metadata and _is_scalar(metadata['image_hash']):
        query['image_hash'] = metadata['image_hash']

    if 'dimensions' in metadata:
        dims = metadata['dimensions']
        if isinstance(dims, dict):
            if 'width' in dims and _is_scalar(dims['width']):
                query['dimensions.width'] = dims['width']
            if 'height' in dims and _is_scalar(dims['height']):
                query['dimensions.height'] = dims['height']

    if 'pipeline_stage' in metadata and _is_scalar(metadata['pipeline_stage']):
        query['pipeline_stage'] = metadata['pipeline_stage']

    return query

def resolve_filter_chain(filter_spec):
    """Resolve a filter chain specification into executable steps.
    The filter_spec can reference stored filter configurations."""
    if isinstance(filter_spec, str):
        return [filter_spec]
    elif isinstance(filter_spec, list):
        return filter_spec
    elif isinstance(filter_spec, dict):
        chain = []
        if 'base' in filter_spec:
            stored = collection.find_one({'filter_name': filter_spec['base']})
            if stored and 'chain' in stored:
                chain.extend(stored['chain'])
        if 'append' in filter_spec:
            chain.extend(filter_spec['append'])
        return chain
    return []

def lookup_existing_result(user_query):
    """Check if we already processed this image with these parameters.
    Accepts user-provided query parameters for cache lookup."""
    base_query = {'status': 'completed'}

    if 'lookup_params' in user_query:
        params = user_query['lookup_params']
        # Merge user lookup params into the base query
        # Only allow string values to prevent operator injection
        for key, value in params.items():
            if key.startswith('_') or key.startswith('$'):
                continue  # skip internal and operator fields
            if not isinstance(value, (str, int, float, bool)):
                continue  # only allow scalar values
            base_query[key] = value

    return collection.find_one(base_query)

def apply_filter(image, filter_name):
    if filter_name == 'grayscale':
        return image.convert('L')
    elif filter_name == 'thumbnail':
        image.thumbnail((128, 128))
        return image
    elif filter_name == 'rotate90':
        return image.rotate(90)
    return image

def flush_pending_operations():
    global pending_operations
    if pending_operations:
        try:
            collection.insert_many(pending_operations)
        except Exception:
            pass
    pending_operations = []

@app.route('/process', methods=['POST'])
def process_image():
    if shutdown_requested:
        return jsonify({'error': 'Server shutting down'}), 503

    data = request.get_json()
    if not data or 'image' not in data:
        return jsonify({'error': 'No image provided'}), 400

    # Check cache first
    cached = lookup_existing_result(data)
    if cached:
        return jsonify({
            'status': 'cached',
            'result_id': str(cached['_id']),
            'image_hash': cached.get('image_hash', '')
        })

    try:
        image_data = base64.b64decode(data['image'])
        image = Image.open(io.BytesIO(image_data))
    except Exception as e:
        return jsonify({'error': 'Invalid image data'}), 400

    img_hash = compute_image_hash(image_data)

    filters = resolve_filter_chain(data.get('filters', 'grayscale'))

    for f in filters:
        if validate_filter_name(f):
            image = apply_filter(image, f)

    buf = io.BytesIO()
    image.save(buf, format='PNG')
    result_data = base64.b64encode(buf.getvalue()).decode()

    doc = {
        'image_hash': img_hash,
        'dimensions': {'width': image.width, 'height': image.height},
        'pipeline_stage': 'completed',
        'status': 'completed',
        'result': result_data,
        'filters_applied': filters
    }

    pending_operations.append(doc)

    if len(pending_operations) >= 10:
        flush_pending_operations()

    return jsonify({'status': 'processed', 'image_hash': img_hash})

@app.route('/query', methods=['POST'])
def query_results():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No query provided'}), 400

    metadata = data.get('metadata', {})
    query = build_query_from_metadata(metadata)

    if not query:
        return jsonify({'error': 'Empty query'}), 400

    results = list(collection.find(query, {'result': 0}).limit(20))
    for r in results:
        r['_id'] = str(r['_id'])

    return jsonify({'results': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
